import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Stage 3 · Computer Operator","description":"Hearth Stage 3 开发模块：设备 agentd、GUI 观察、人工接管、低风险桌面动作、高风险审批与桌面安全边界。","frontmatter":{"title":"Stage 3 · Computer Operator","description":"Hearth Stage 3 开发模块：设备 agentd、GUI 观察、人工接管、低风险桌面动作、高风险审批与桌面安全边界。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3.md","filePath":"delivery/stage-3.md","lastUpdated":1793752688000}'),o={name:"delivery/stage-3.md"};function i(d,t,h,s,n,g){return a(),r("div",null,[...t[0]||(t[0]=[l('<p class="eyebrow">MODULE 3 / 7</p><h1 id="stage-3-·-computer-operator" tabindex="-1">Stage 3 · Computer Operator <a class="header-anchor" href="#stage-3-·-computer-operator" aria-label="Permalink to &quot;Stage 3 · Computer Operator&quot;">​</a></h1><p class="lead">覆盖没有 API 的桌面软件和跨应用流程。顺序是先观察、再接管、再低风险动作，最后才开放高风险动作；无法验证或无法接管时，不允许自动执行。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>Stage 1–2 的恢复、审批、幂等、回执和网页隔离已经稳定。</li><li>已明确设备能力、窗口范围、应用白名单和不可逆动作清单。</li><li>接管与撤销路径先于自动操作完成。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>注册桌面设备。</strong> 实现设备配对、<code>agentd</code> 注册、能力目录、健康检查、权限声明、设备详情、断开与撤销。</li><li><strong>建立观察与接管。</strong> 接入可访问性树、截图、窗口范围、实时接管、键鼠暂停/交还、截图脱敏和审计事件。</li><li><strong>完成低风险 GUI 动作。</strong> 在应用白名单内完成打开文件、定位菜单、填写草稿、导出结果，并用截图/可访问性树验证结果。</li><li><strong>处理半完成与失败。</strong> 检测部分成功、窗口丢失、输入争抢、权限变化和不可恢复状态，提供暂停、接管或回滚。</li><li><strong>开放高风险动作。</strong> 加入隔离虚拟桌面、影响预览、二次确认、不可逆动作清单、桌面快照、补偿脚本和恢复演练。</li><li><strong>完成 Stage 3 发布。</strong> 用至少 5 个真实桌面任务评估完成率、接管体验、安全边界、Token 和人工分钟。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><p>每个增量现在按四层阅读：结果与门槛 → 四个实施工作包 → 工程落点与接口 → 验收演练。工作包可以拆给不同开发者并行，但必须按依赖顺序合并；只完成一个包不等于完成增量。</p><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-3/d3-1.html">D3.1</a> 设备 agentd 与设备可见性</td><td>用户看到可信设备、能力和在线状态</td><td>配对、能力目录、健康检查、撤销</td></tr><tr><td><a href="/hearth-os/delivery/stage-3/d3-2.html">D3.2</a> GUI 观察与人工接管</td><td>用户能看到窗口、暂停、操作并交还</td><td>接管界面、窗口范围、状态记录、截图脱敏</td></tr><tr><td><a href="/hearth-os/delivery/stage-3/d3-3.html">D3.3</a> 低风险 GUI 动作与验证</td><td>白名单应用内完成低风险操作并展示证据</td><td>应用白名单、动作预览、结果验证、失败重试</td></tr><tr><td><a href="/hearth-os/delivery/stage-3/d3-4.html">D3.4</a> 高风险 GUI 与 Stage 3 发布</td><td>高风险动作有影响说明、二次确认与补偿</td><td>隔离桌面、审批、快照、恢复、5 个真实任务</td></tr></tbody></table><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] 至少 5 个真实桌面任务可以完成并验证。</li><li>[ ] 接管流程可用，用户能暂停、操作、交还或终止。</li><li>[ ] GUI 失败不会留下半完成的高风险状态。</li><li>[ ] 不读取密码库、不越权修改系统安全设置。</li><li>[ ] Token 和人工分钟在可接受范围，用户理解撤销或补偿方式。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不在无法验证、无法接管时自动执行桌面动作。</li><li>不开放无边界的系统级控制。</li><li>不把 OCR 或截图识别当作唯一事实来源。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>进入 <a href="/hearth-os/delivery/stage-4.html">Stage 4 · 主动个人 Agent</a>，在已有恢复与审批之上增加有限主动性。</p>',16)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
